style.css:
@-moz-document domain("character.ai") {
/* Main background */
body {
    background-color: #121212 !important;
    color: #ffffff !important;
}

/* Individual chat bubbles */
#chat-messages .bg-surface-elevation-2.opacity-85 {
    background-color: #1e1e1e !important;
    border: 1px solid #444444 !important;
    opacity: 1 !important;
    border-radius: 12px !important;
}

/* Chat message text */
#chat-messages .prose,
#chat-messages .prose p,
#chat-messages .prose span,
#chat-messages .prose strong,
#chat-messages .prose em,
#chat-messages .prose li {
    color: #ffffff !important;
}

/* Chat bubble hover */
#chat-messages .bg-surface-elevation-2.opacity-85:hover {
    background-color: #333333 !important;
}

/* Links inside messages */
#chat-messages .prose a {
    color: #bb86fc !important;
}

/* Edited messages */
#chat-messages .edited {
    outline: none !important;
}
}
